import { ValidationError } from "..";
import type { Source } from "../callbag";
import { FetchError, ResponseError } from "./Errors";
import { RequestOptions, ResponseDictValue, SuccessResponsesFromResponseDict } from "./RequestOptions";
/**
 * A function that creates a reactive stream that
 * emits the decoded server response or errors, if there was
 * an issue in sending the request or in processing
 * the response.
 *
 * If the status code provided is in `responseDictionary`, and is
 * able to be parsed without issue, then the stream will emit
 * a single value and end. The value will have the following shape:
 * ```
 * {
 *   statusCode: number; // HTTP status code
 *   description: string; // Description of the response.
 *   result: any; // The parsed result, if any. If none, then this will be `undefined`.
 * }
 * ```
 *
 * If the status code provided is in `responseDictionary`, but the
 * response could not be parsed, then the stream will end with
 * {@link ResponseDecodeError}.
 *
 * If the status code provided is not in `responseDictionary`,
 * then the stream will end with an
 * {@link UndocumentedResponseError} error.
 *
 * @param param.jsonParse A parse function to use when deserializing
 *     local data from JSON.
 * @param param.response The JSON string response to parse.
 * @param param.responseDictionary The dictionary of expected responses
 *     keyed by status code. If the status code received is not in this
 *     dictionary, then the stream will end with an
 *     {@link UndocumentedResponseError} error.
 * @param param.statusCode The HTTP status code associated with the
 *     response received.
 * @returns A pullable callbag source that emits the decoded
 *     value of a string response or an error.
 */
export declare function request$<R extends Record<number, ResponseDictValue>>(requestOptions: RequestOptions & {
    readonly responseDictionary: R;
}): Source<SuccessResponsesFromResponseDict<R>, ResponseError | ValidationError | FetchError>;
